/// <summary>
/// MPJ_24248 Price Data Extract
/// </summary>
Public class METPriceChangeEventBasePrice
{
}

Method.Source:
    /// <summary>
    /// Process the change track
    /// Kept this process light weight due to volume of records
    /// </summary>
    /// <param name = "_itemBasePrice">Item Base Price</param>
    public static void metProcessTrackChange(GUPItemBasePrice _itemBasePrice)
    {
        METPriceChangeTracking  priceChangeTracking;

        try
        {
            if (_itemBasePrice.PriceType == GUPBasePriceType::BasePriceInventoryCost)
            {
                ttsbegin;
                priceChangeTracking.clear();
                                
                priceChangeTracking.SourceCrud  = SysAppCRUDOperation::Create;
                priceChangeTracking.ChangeType  = METPriceChangeType::BasePrice;
                priceChangeTracking.setCommonValues(_itemBasePrice);
                priceChangeTracking.QuantityAmountFrom = _itemBasePrice.PriceQty ? _itemBasePrice.PriceQty : 1;

                priceChangeTracking.VersionId   = _itemBasePrice.VersionId;
                priceChangeTracking.InventSiteID = InventDim::find(_itemBasePrice.InventDimId).InventSiteId;
                priceChangeTracking.ItemId      = _itemBasePrice.ItemId;
                priceChangeTracking.FromDate    = _itemBasePrice.FromDate ? _itemBasePrice.FromDate : DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimezone());
                priceChangeTracking.ToDate      = _itemBasePrice.ToDate;
                priceChangeTracking.Price       = _itemBasePrice.Price;
                priceChangeTracking.PriceQty    = _itemBasePrice.PriceQty;
                priceChangeTracking.UnitId      = _itemBasePrice.UnitId;
                priceChangeTracking.VendAccount = _itemBasePrice.AccountRelation;

                priceChangeTracking.insert();
                ttscommit;
            }
        }
        catch
        {
            Error("@MET:PriceChangeTrackingCreationFailed");
        }
    }
